def convert(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s
    rows = [[] for _ in range(numRows)]
    idx = 0
    step = 1
    for ch in s:
        rows[idx].append(ch)
        if idx == 0:
            step = 1
        elif idx == numRows - 1:
            step = -1
        idx += step
    return "".join("".join(row) for row in rows)

